using System;
using System.Linq;
namespace DoomSNESed {
    public static class AudioCli {
        public static AudioProject Parse(string[] args,string source,string resources){var project=new AudioProject();if(!args.Any(a=>a.StartsWith("--music=")||a.StartsWith("--wav=")))return project;var rom=new Rom(source,resources);var slots=AudioRom.Sounds(rom.Bytes,resources);int voices=6;double duration=0;foreach(string arg in args){if(arg.StartsWith("--music-voices="))voices=int.Parse(arg.Substring(15));if(arg.StartsWith("--music-seconds="))duration=double.Parse(arg.Substring(16),System.Globalization.CultureInfo.InvariantCulture);}foreach(string arg in args){if(arg.StartsWith("--music=")){string pair=arg.Substring(8);int colon=pair.IndexOf(':');Bin.Require(colon>0&&colon+1<pair.Length,"Use --music=E1M1:C:\\path\\song.mid");string map=MusicTargets.Canonical(pair.Substring(0,colon).ToUpperInvariant());project.Music.RemoveAll(m=>m.Map==map);var notes=MusicImport.Read(pair.Substring(colon+1));var mapping=MusicBank.Automatic(rom.Bytes,notes);project.Music.Add(args.Contains("--auto-music")?MusicOptimize.Fit(notes,map,voices,duration,!args.Contains("--one-shot-music"),mapping,args.Contains("--allow-voice-reduction")):MusicImport.Convert(notes,map,voices,duration,!args.Contains("--one-shot-music"),mapping));}else if(arg.StartsWith("--wav=")){string pair=arg.Substring(6);int colon=pair.IndexOf(':');Bin.Require(colon>0&&colon+1<pair.Length,"Use --wav=10:C:\\path\\sound.wav");int wave=int.Parse(pair.Substring(0,colon));var slot=slots.FirstOrDefault(s=>s.Wave==wave);Bin.Require(slot!=null,"Unknown native waveform number.");project.Sounds.RemoveAll(s=>s.Wave==wave);project.Sounds.Add(WavImport.Convert(pair.Substring(colon+1),slot,!args.Contains("--keep-silence"),!args.Contains("--no-normalize"),args.Contains("--fit-sounds"),args.Contains("--loop-sounds")));}}return project;}
        public static string Report(Rom rom){if(!AudioBuild.HasAudio(rom.Project))return "";return "\r\nAUDIO IMPORTS\r\n"+string.Join("\r\n",rom.Project.Audio.Music.Select(m=>m.Map+" <- "+m.Name+"\r\n"+m.Report).Concat(rom.Project.Audio.Sounds.Select(s=>"Wave "+s.Wave+" <- "+s.Name+"\r\n"+s.Report)).ToArray())+"\r\nROM allocation: music/tables "+rom.Budget.Music+" B, sounds "+rom.Budget.Sounds+" B; peak custom sequence "+rom.Budget.ApuSequenceMax+" / 9383 SPC bytes.\r\n";}
    }
}
